examples.template:
MonarchColumnsBlock(ratio = {{ratio|double}}f) {
    column {
        MonarchText(
            text = buildAnnotatedString {
                withStyle(SpanStyle(fontWeight = FontWeight.SemiBold)) { append({{columns.0.lead}}) }
                append({{columns.0.text}})
            },
        )
    }
    column {
        MonarchText(
            text = buildAnnotatedString {
                withStyle(SpanStyle(fontWeight = FontWeight.SemiBold)) { append({{columns.1.lead}}) }
                append({{columns.1.text}})
            },
        )
    }
}

